1	// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
2	// SPDX-FileCopyrightText: 2026 Julian Kammerer
3	//
4	// SPDX-License-Identifier: GPL-3.0-or-later
5	
6	#pragma once
7	#define AAD_MAX_LEN 32
8	#define aad_uint_t uint256_t
9	
10	typedef enum prep_auth_data_state_t{
11	  IDLE,
12	  AAD_STATE,
13	  CIPHERTEXT,
14	  LENGTHS
15	}prep_auth_data_state_t;
16	
17	typedef struct prep_auth_data_fsm_t{
18	  // Outputs
19	  uint1_t ready_for_axis_in;
20	  stream(axis128_t) axis;
21	}prep_auth_data_fsm_t;
22	prep_auth_data_fsm_t prep_auth_data_fsm(
23	  // Inputs
24	  uint8_t aad[AAD_MAX_LEN],
25	  uint8_t aad_len,
26	  stream(axis128_t) axis_in,
27	  uint1_t ready_for_axis_out
28	){
29	  prep_auth_data_fsm_t o;
30	  // FSM that adds leading and trailing bytes around the ciphertext stream
31	  // to prepare the stream to be authenticated by Poly1305
32	  // AAD || padding || ciphertext || padding || AAD length || ciphertext length
33	  static prep_auth_data_state_t state;
34	  static uint8_t aad_reg[AAD_MAX_LEN];
35	  static uint16_t counter;
36	
37	  // Default not ready for incoming data
38	  o.ready_for_axis_in = 0;
39	  // Default not outputting data
40	  stream(axis128_t) axis128_null = {0};
41	  o.axis = axis128_null;
42	  
43	  if(state == IDLE)
44	  {
45	    // Wait for incoming ciphertext
46	    if(axis_in.valid)
47	    {
48	      // Not yet ready for data until CIPHERTEXT 
49	      // If have AAD, then output it first
50	      if(aad_len > 0)
51	      {
52	        // AAD is first, save input into reg for shifting out
53	        aad_reg = aad;
54	        // and init counter with AAD length
55	        counter = aad_len;
56	        state = AAD_STATE;
57	      }
58	      else
59	      {
60	        // No AAD, so ciphertext is first
61	        state = CIPHERTEXT;
62	        counter = 0;
63	      }
64	    }
65	  }
66	  else if(state == AAD_STATE)
67	  {
68	    // Output up to 128b|16 bytes of AAD this cycle
69	    // AAD is conveiniently padded to multiple of 16 bytes
70	    // so always full tkeep, tdata=0 for padding
71	    for(int32_t i=0; i<16; i+=1)
72	    {
73	      if(counter > i){
74	        o.axis.data.tdata[i] = aad_reg[i];
75	      }
76	      o.axis.data.tkeep[i] = 1;
77	    }
78	    o.axis.valid = 1;
79	
80	    // Count AAD bytes as xfer happens
81	    if(o.axis.valid & ready_for_axis_out)
82	    {
83	      // More AAD bytes?
84	      if(counter > 16)
85	      {
86	        // Prepare next AAD bytes to be at bottom of the array
87	        ARRAY_SHIFT_DOWN(aad_reg, AAD_MAX_LEN, 16)
88	        counter -= 16;  
89	      }
90	      else
91	      {
92	        // No more AAD bytes, CIPHERTEXT is next
93	        state = CIPHERTEXT;
94	        counter = 0;
95	      }
96	    }
97	  }
98	  else if(state == CIPHERTEXT)
99	  {
100	    // Pass through ciphertext
101	    o.axis = axis_in;
102	    o.ready_for_axis_in = ready_for_axis_out;
103	    // last cycle of ciphertext is not the last cycle of output stream
104	    o.axis.data.tlast = 0;
105	    // Data needs to be padded to 16 bytes with zeros
106	    // during cycles with partial tkeep
107	    for(int32_t i=0; i<16; i+=1)
108	    {
109	      o.axis.data.tkeep[i] = 1;
110	      if(~axis_in.data.tkeep[i]){
111	        o.axis.data.tdata[i] = 0;
112	      }
113	    }
114	
115	    // Count ciphertext length as xfer happens
116	    if(axis_in.valid & o.ready_for_axis_in){
117	      counter += axis128_keep_count(axis_in.data);
118	      // As last cycle on input ciphertest passes, move to next state
119	      if(axis_in.data.tlast){
120	        state = LENGTHS;
121	      }
122	    }
123	  }
124	  else //if(state == LENGTHS)
125	  {
126	    // Two 64b lengths of AAD and ciphertext
127	    // fit into one 128b AXIS cycle
128	    int32_t pos = 0;
129	    // AAD length
130	    for(int32_t i=0; i<8; i+=1)
131	    {
132	      o.axis.data.tdata[pos] = aad_len >> (i*8);
133	      o.axis.data.tkeep[pos] = 1;
134	      pos += 1;
135	    }
136	    // Ciphertext length
137	    for(int32_t i=0; i<8; i+=1)
138	    {
139	      o.axis.data.tdata[pos] = counter >> (i*8);
140	      o.axis.data.tkeep[pos] = 1;
141	      pos += 1;
142	    }
143	    // Last cycle of output stream
144	    o.axis.data.tlast = 1;
145	    o.axis.valid = 1;
146	
147	    // As xfer happens, go back to idle
148	    if(o.axis.valid & ready_for_axis_out)
149	    {
150	      state = IDLE;
151	    }
152	  }
153	  return o;
154	}
