33	// The ChaCha20 quarter round function
34	// TODO abcd are constants and might get better results if this function made into macro
35	chacha20_state quarter_round(chacha20_state s, uint4_t a, uint4_t b, uint4_t c, uint4_t d)
36	{
37	    chacha20_state o = s;
38	
39	    // decompose ops
40	    uint32_t a1 = o.state[a] + o.state[b];
41	    uint32_t d1 = rotl32_16(o.state[d] ^ a1);
42	    uint32_t c1 = o.state[c] + d1;
43	    uint32_t b1 = rotl32_12(o.state[b] ^ c1);
44	    uint32_t a2 = a1 + b1;
45	    uint32_t d2 = rotl32_8(d1 ^ a2);
46	    uint32_t c2 = c1 + d2;
47	    uint32_t b2 = rotl32_7(b1 ^ c2);
48	    
49	    // join output
50	    o.state[a] = a2;
51	    o.state[b] = b2;
52	    o.state[c] = c2;
53	    o.state[d] = d2;
54	
55	    return o;
56	}
