58	chacha20_state chacha20_block_step(chacha20_state state0){
59	    // make a giant pipeline with 8 parallel ops
60	    chacha20_state state1 = quarter_round(state0, 0, 4, 8, 12);
61	    chacha20_state state2 = quarter_round(state1, 1, 5, 9, 13);
62	    chacha20_state state3 = quarter_round(state2, 2, 6, 10, 14);
63	    chacha20_state state4 = quarter_round(state3, 3, 7, 11, 15);
64	    chacha20_state state5 = quarter_round(state4, 0, 5, 10, 15);
65	    chacha20_state state6 = quarter_round(state5, 1, 6, 11, 12);
66	    chacha20_state state7 = quarter_round(state6, 2, 7, 8, 13);
67	    chacha20_state state8 = quarter_round(state7, 3, 4, 9, 14);
68	    return state8;
69	}
