71	// ChaCha20 block function pipeline
72	chacha20_state chacha20_block(chacha20_state state)
73	{
74	    chacha20_state output;
75	
76	    // 1. do 20 steps (2x each step) (giant pipeline)
77	    // TODO could be loop?
78	    chacha20_state step1  = chacha20_block_step(state);
79	    chacha20_state step2  = chacha20_block_step(step1);
80	    chacha20_state step3  = chacha20_block_step(step2);
81	    chacha20_state step4  = chacha20_block_step(step3);
82	    chacha20_state step5  = chacha20_block_step(step4);
83	    chacha20_state step6  = chacha20_block_step(step5);
84	    chacha20_state step7  = chacha20_block_step(step6);
85	    chacha20_state step8  = chacha20_block_step(step7);
86	    chacha20_state step9  = chacha20_block_step(step8);
87	    chacha20_state step10 = chacha20_block_step(step9);
88	    
89	    // 2. final parallel add
90	    uint4_t i;
91	    for (i = 0; i < CHACHA20_STATE_NWORDS; i+=1)
92	    {
93	        output.state[i] = step10.state[i] + state.state[i];
94	    }
95	
96	    return output;
97	}
