100	// ChaCha20 initialization function
101	chacha20_state chacha20_init(
102	  uint8_t key[CHACHA20_KEY_SIZE], 
103	  uint8_t nonce[CHACHA20_NONCE_SIZE], 
104	  uint32_t counter
105	){
106	    chacha20_state state;
107	    // Set the initial state (constants + key + nonce)
108	    // "expand 32-byte k"
109	    state.state[0] = 0x61707865; // "apxe"
110	    state.state[1] = 0x3320646e; // "3 dn"
111	    state.state[2] = 0x79622d32; // "yb-2"
112	    state.state[3] = 0x6b206574; // "k et"
113	
114	    // Key
115	    uint32_t key_as_u32s[CHACHA20_KEY_SIZE/4];
116	    for(uint32_t i = 0; i < CHACHA20_KEY_SIZE/4; i+=1)
117	    {
118	      uint16_t lsbs = uint8_uint8(key[(i*4)+1], key[(i*4)+0]);
119	      uint16_t msbs = uint8_uint8(key[(i*4)+3], key[(i*4)+2]);
120	      key_as_u32s[i] = uint16_uint16(msbs, lsbs);
121	    }
122	    for(uint32_t i = 0; i < CHACHA20_KEY_SIZE/4; i+=1)
123	    {
124	        state.state[4 + i] = key_as_u32s[i];
125	    }
126	
127	    // Counter
128	    state.state[12] = counter;
129	
130	    // Nonce
131	    uint32_t nonce_as_u32s[CHACHA20_NONCE_SIZE/4];
132	    for(uint32_t i = 0; i < CHACHA20_NONCE_SIZE/4; i+=1)
133	    {
134	      uint16_t lsbs = uint8_uint8(nonce[(i*4)+1], nonce[(i*4)+0]);
135	      uint16_t msbs = uint8_uint8(nonce[(i*4)+3], nonce[(i*4)+2]);
136	      nonce_as_u32s[i] = uint16_uint16(msbs, lsbs);
137	    }
138	    for(uint32_t i = 0; i < CHACHA20_NONCE_SIZE/4; i+=1)
139	    {
140	        state.state[13 + i] = nonce_as_u32s[i];
141	    }
142	
143	    return state;
144	}
